  async function validateGlbPath(path){let url;try{url=new URL(path,location.href);}catch{return {ok:false,reason:'URL 형식 오류'};}if(url.origin!==location.origin)return {ok:false,reason:'다른 출처 URL은 검사하지 않음'};if(!url.pathname.startsWith('/projects/P006/assets/'))return {ok:false,reason:'웹 자산 경로가 아님 (서버 내부 경로는 브라우저 검사 불가)'};if(!/\.glb$/i.test(url.pathname))return {ok:false,reason:'웹 미리보기는 GLB 경로가 필요함'};let response;try{response=await fetch(url.href,{headers:{Range:'bytes=0-11'},cache:'no-store'});}catch(e){return {ok:false,reason:`요청 실패: ${e.message||'network error'}`};}if(new URL(response.url,location.href).origin!==location.origin){try{await response.body?.cancel();}catch{}return {ok:false,reason:'외부 출처로 리디렉션됨'};}if(!response.ok){try{await response.body?.cancel();}catch{}return {ok:false,reason:`HTTP ${response.status}`};}const mime=response.headers.get('content-type')||'미확인';if(/text\/html/i.test(mime)){try{await response.body?.cancel();}catch{}return {ok:false,reason:'HTML 응답 (GLB 파일이 아님)'};}let bytes;try{if(response.body){const reader=response.body.getReader(),chunks=[];let length=0;while(length<12){const next=await reader.read();if(next.done)break;const take=next.value.slice(0,12-length);chunks.push(take);length+=take.length;}await reader.cancel();bytes=new Uint8Array(length);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}}else bytes=new Uint8Array(await response.arrayBuffer()).slice(0,12);}catch{return {ok:false,reason:'파일 헤더 읽기 실패'};}if(!bytes||bytes.length<4||String.fromCharCode(...bytes.slice(0,4))!=='glTF')return {ok:false,reason:'GLB magic header 불일치'};const range=response.headers.get('content-range'),size=range?.match(/\/(\d+)$/)?.[1]||response.headers.get('content-length')||null;return {ok:true,mime,size,range:response.status===206?'부분 응답':'요청 Range 미지원 · 본문 전송은 첫 12바이트 후 취소'};}
